//! Pinned regexp-engine divergences from GNU (P3.3 design section 12).
//!
//! Each test holds GNU's answer, generated by
//! `NEOVM_ORACLE_MODE=refresh UPDATE_EXPECT=1`.  A test written with
//! `assert_oracle_divergence_expect` is an EXPECTED FAILURE: it passes while
//! Neomacs still answers differently, and fails once the divergence is fixed,
//! so the fixing commit flips it to `assert_oracle_parity_expect`.
//!
//! | id | case | status |
//! |----|------|--------|
//! | D1 | unibyte buffer, `\w` on raw byte 0xA9 | open |
//! | D2 | unibyte `"\351\200y"`, backward POSIX `\b\(\w\)` | open |
//! | D3 | failed `string-match` after a buffer search, `(match-data t)` | open |
//! | D4 | `[[:upper:]]` on U+01C5 (a titlecase digraph) | open |
//! | D5 | `\(?:a?\)*?b` never terminates (no `CHECK_INFINITE_LOOP` for `on_failure_jump_nastyloop`) | fixed (U0.5) |
//! | D6 | `\(a\|\)+?x` signals a spurious "Stack overflow in regexp matcher" | fixed (U0.5) |
//! | D7 | the Pike fallback masks GNU's "Stack overflow in regexp matcher" | fixed (U0.5) |
//!
//! A fixed divergence keeps its test as a parity regression guard
//! (`assert_oracle_parity_expect`, same GNU expectation).

use crate::common::return_if_neovm_enable_oracle_proptest_not_set;

#[test]
fn oracle_pin_regexp_d1_unibyte_word_on_raw_byte() {
    return_if_neovm_enable_oracle_proptest_not_set!();

    let form = r#"(with-temp-buffer
      (set-buffer-multibyte nil)
      (insert #xc3 #xa9)
      (goto-char 2)
      (list (looking-at "\\w") (looking-at "\\W")))"#;
    let expect = expect_test::expect![[r#""OK (t nil)""#]];
    crate::common::assert_oracle_divergence_expect(form, expect);
}

#[test]
fn oracle_pin_regexp_d2_posix_backward_word_boundary_on_eight_bit() {
    return_if_neovm_enable_oracle_proptest_not_set!();

    let form = r#"(with-temp-buffer
      (set-buffer-multibyte nil)
      (insert "\351\200y")
      (goto-char (point-max))
      (list (and (posix-search-backward "\\b\\(\\w\\)" nil t) (point))
            (match-beginning 0) (match-end 0) (match-beginning 1) (match-end 1)))"#;
    let expect = expect_test::expect![[r#""OK (3 3 4 3 4)""#]];
    crate::common::assert_oracle_divergence_expect(form, expect);
}

#[test]
fn oracle_pin_regexp_d3_failed_string_match_after_buffer_search() {
    return_if_neovm_enable_oracle_proptest_not_set!();

    let form = r#"(with-temp-buffer
      (insert "abc")
      (goto-char 1)
      (re-search-forward "b")
      (list (string-match "zzz" "abc")
            (let ((md (match-data t)))
              (list (length md) (bufferp (car (last md)))))))"#;
    let expect = expect_test::expect![[r#""OK (nil (2 nil))""#]];
    crate::common::assert_oracle_divergence_expect(form, expect);
}

#[test]
fn oracle_pin_regexp_d4_upper_class_on_titlecase_digraph() {
    return_if_neovm_enable_oracle_proptest_not_set!();

    let form = r#"(let ((case-fold-search nil))
      (list (string-match "[[:upper:]]" "ǅ")
            (string-match "[[:lower:]]" "ǅ")))"#;
    let expect = expect_test::expect![[r#""OK (0 nil)""#]];
    crate::common::assert_oracle_divergence_expect(form, expect);
}

#[test]
fn oracle_pin_regexp_d5_nullable_nongreedy_star_terminates() {
    return_if_neovm_enable_oracle_proptest_not_set!();

    let form = r#"(list (string-match "\\(?:a?\\)*?b" "aaaac")
            (string-match "\\(?:a?\\)*?b" "c")
            (string-match "\\(?:a?\\)*?b" "aaab")
            (match-data))"#;
    let expect = expect_test::expect![[r#""OK (nil nil 0 (0 4))""#]];
    crate::common::assert_oracle_parity_expect(form, expect);
}

#[test]
fn oracle_pin_regexp_d6_nullable_nongreedy_plus_has_no_spurious_overflow() {
    return_if_neovm_enable_oracle_proptest_not_set!();

    let form = r#"(list (condition-case err (string-match "\\(a\\|\\)+?x" "aaaay")
              (error (list 'error err)))
            (condition-case err
                (list (string-match "\\(a\\|\\)+?x" "aaaax") (match-data))
              (error (list 'error err))))"#;
    let expect = expect_test::expect![[r#""OK (nil (0 (0 5 3 4)))""#]];
    crate::common::assert_oracle_parity_expect(form, expect);
}

#[test]
fn oracle_pin_regexp_d7_pike_fallback_masks_overflow() {
    return_if_neovm_enable_oracle_proptest_not_set!();

    let form = r#"(let ((s (apply #'concat (make-list 150000 "ab"))))
      (condition-case err (string-match "\\(?:a\\|b\\)*c" s)
        (error (list 'error err))))"#;
    let expect =
        expect_test::expect![[r#""OK (error (error \"Stack overflow in regexp matcher\"))""#]];
    crate::common::assert_oracle_parity_expect(form, expect);
}

#[test]
fn oracle_pin_regexp_d7_pike_fallback_masks_overflow_at_one_candidate() {
    return_if_neovm_enable_oracle_proptest_not_set!();

    // Only position 0 can start a match, so the whole search is one candidate:
    // GNU's backtracker runs out of fail stack; Neomacs's budgeted one hands
    // the candidate to the Pike VM, which cannot overflow, so the Pike run's
    // reach decides whether the backtracker must answer instead.  The
    // 20K-character twin stays under GNU's limit and must answer nil on both.
    let form = r#"(let ((long (concat "x" (apply #'concat (make-list 100000 "ab"))))
          (short (concat "x" (apply #'concat (make-list 10000 "ab")))))
      (list (condition-case err (string-match "x\\(?:a\\|b\\)*c" long)
              (error (list 'error err)))
            (condition-case err (string-match "x\\(?:a\\|b\\)*c" short)
              (error (list 'error err)))))"#;
    let expect = expect_test::expect![[
        r#""OK ((error (error \"Stack overflow in regexp matcher\")) nil)""#
    ]];
    crate::common::assert_oracle_parity_expect(form, expect);
}
